const HOSTS = {
  nfse:     { url: "https://api.nfe.io",               chave: process.env.NFEIO_INVOICE_KEY! },
  produto:  { url: "https://api.nfse.io",              chave: process.env.NFEIO_INVOICE_KEY! },
  cnpj:     { url: "https://legalentity.api.nfe.io",   chave: process.env.NFEIO_DATA_KEY! },
  cpf:      { url: "https://naturalperson.api.nfe.io", chave: process.env.NFEIO_DATA_KEY! },
  cep:      { url: "https://address.api.nfe.io",       chave: process.env.NFEIO_DATA_KEY! },
  consulta: { url: "https://nfe.api.nfe.io",           chave: process.env.NFEIO_DATA_KEY! },
} as const;

export async function chamar(alvo: keyof typeof HOSTS, caminho: string, init: RequestInit = {}) {
  const { url, chave } = HOSTS[alvo];
  const r = await fetch(url + caminho, {
    ...init,
    headers: { Authorization: chave, ...(init.headers ?? {}) },
  });
  if (!r.ok) throw new Error(`${alvo} ${caminho} -> ${r.status}`);
  return r;
}

import time

FINAIS_NFSE = {"Issued", "IssueFailed", "Cancelled", "CancelFailed"}


def acompanhar_nfse(sessao, base, company_id, nota_id, tentativas=20, intervalo=5):
    for _ in range(tentativas):
        r = sessao.get(f"{base}/v1/companies/{company_id}/serviceinvoices/{nota_id}", timeout=60)
        r.raise_for_status()
        nota = r.json()
        if nota.get("flowStatus") in FINAIS_NFSE:
            if nota["flowStatus"] != "Issued":
                raise RuntimeError(f"nota nao autorizada: {nota['flowStatus']} - {nota.get('flowMessage')}")
            return nota
        time.sleep(intervalo)
    raise TimeoutError("ainda em processamento; prefira webhook a polling longo")

type Envelope = { payload?: Record<string, any> } & Record<string, any>;

export function normalizar(corpo: Envelope, tipoDoHeader: string | null) {
  const documento = corpo.payload ?? corpo;            // NFS-e envelopada; NF-e/NFC-e achatada
  const resultado = documento.flowStatus ?? documento.status;   // NFS-e usa flowStatus
  const emissor   = documento.provider ?? documento.issuer;     // NFS-e: provider; NF-e: issuer
  const cliente   = documento.borrower ?? documento.buyer;      // NFS-e: borrower; NF-e: buyer
  return { tipo: tipoDoHeader, resultado, emissor, cliente, documento };
}

import requests

def emitir_nfse(sessao, base, company_id, nota):
    r = sessao.post(f"{base}/v1/companies/{company_id}/serviceinvoices", json=nota, timeout=90)
    if r.status_code == 400:
        for erro in r.json().get("errors", []):
            print(f"  campo/regra: {erro.get('code')} -> {erro.get('message')}")
        raise ValueError("payload invalido; corrija antes de reenviar")
    if r.status_code == 408:
        # NAO reenvie: consulte pelo externalId antes
        achada = sessao.get(
            f"{base}/v1/companies/{company_id}/serviceinvoices/external/{nota['externalId']}", timeout=60)
        if achada.ok:
            return achada.json()
        raise TimeoutError("timeout sem nota localizada; verifique manualmente")
    r.raise_for_status()
    return r.json()

from datetime import datetime, timezone

def alerta_certificados(sessao, base, company_ids, dias=30):
    pendentes = []
    for cid in company_ids:
        r = sessao.get(f"{base}/v2/companies/{cid}/certificates", timeout=60)
        if r.status_code == 404:
            pendentes.append({"company_id": cid, "situacao": "sem certificado"})
            continue
        r.raise_for_status()
        for cert in r.json().get("certificates", []):
            validade = datetime.fromisoformat(cert["validUntil"].replace("Z", "+00:00"))
            faltam = (validade - datetime.now(timezone.utc)).days
            if faltam <= dias:
                pendentes.append({"company_id": cid, "titular": cert.get("subject"),
                                  "vence_em_dias": faltam, "validUntil": cert["validUntil"]})
    return pendentes
